INSERT INTO navigator_overrides (module, section_name, probe, items, sort_order) VALUES
('appendix', 'RLQ Survey — Graded Compression Technique', 'Linear 9–15 MHz | Start at point of maximal tenderness', '[{"id":"app_survey_0","label":"Identify point of maximal tenderness (McBurney''s point)","detail":"One-third of the way from RASIS to umbilicus","critical":true},{"id":"app_survey_1","label":"Apply graded compression to displace bowel gas","detail":"Slow, steady pressure — do not release suddenly","critical":true},{"id":"app_survey_2","label":"Identify psoas muscle as posterior landmark","detail":"Hyperechoic linear structure in the right iliac fossa","critical":false},{"id":"app_survey_3","label":"Identify iliac vessels (CIA, EIA, EIV)","detail":"Pulsatile artery and compressible vein","critical":false},{"id":"app_survey_4","label":"Identify cecum (blind-ending saccular structure with haustra)","detail":"Trace inferiorly to find the appendix origin","critical":true},{"id":"app_survey_5","label":"Scan in grid pattern over the RLQ","detail":"Systematic approach reduces non-visualization rate","critical":false},{"id":"app_survey_6","label":"If not found: check retrocecal position (roll patient left)","detail":"Retrocecal appendix is the most common cause of non-visualization","critical":false}]', 0),
('appendix', 'Appendix Identification and Measurement', 'Linear 9–15 MHz | Transverse and longitudinal planes', '[{"id":"app_id_0","label":"Identify appendix arising from posteromedial cecum","detail":"2–3 cm below the ileocecal valve","critical":true},{"id":"app_id_1","label":"Confirm blind-ending structure (no peristalsis)","detail":"Distinguish from terminal ileum (which peristalsises)","critical":true},{"id":"app_id_2","label":"Measure outer-wall-to-outer-wall diameter (transverse plane)","detail":"Normal ≤6 mm; >7 mm = appendicitis","critical":true},{"id":"app_id_3","label":"Assess compressibility (normal appendix compresses)","detail":"Non-compressible = abnormal","critical":true},{"id":"app_id_4","label":"Assess mural stratification (3 layers: mucosa, muscularis, serosa)","detail":"Loss of stratification = gangrenous appendicitis","critical":true},{"id":"app_id_5","label":"Look for appendicolith (hyperechoic focus with posterior shadowing)","detail":"Appendicolith + tenderness = high risk for perforation","critical":true},{"id":"app_id_6","label":"Assess wall thickness (normal <3 mm)","detail":">3 mm = wall thickening","critical":false}]', 1),
('appendix', 'Periappendiceal Assessment (Inflammation / Perforation)', 'Linear 9–15 MHz | Reduce compression slightly', '[{"id":"app_peri_0","label":"Assess periappendiceal fat echogenicity","detail":"Hyperechoic fat = periappendiceal inflammation","critical":true},{"id":"app_peri_1","label":"Assess for free fluid (periappendiceal or pelvic)","detail":"Free fluid = perforation or peritonitis","critical":true},{"id":"app_peri_2","label":"Assess for appendiceal abscess (complex fluid collection)","detail":"Complex fluid adjacent to appendix = complicated appendicitis","critical":true},{"id":"app_peri_3","label":"Scan right paracolic gutter for free fluid","detail":"Fluid tracking superiorly = significant peritonitis","critical":false},{"id":"app_peri_4","label":"Scan pelvis (pouch of Douglas / rectovesical pouch) for free fluid","detail":"Pelvic free fluid in RLQ pain = perforation until proven otherwise","critical":false},{"id":"app_peri_5","label":"Assess for mesenteric lymphadenopathy","detail":"Nodes >1 cm short axis in cluster = mesenteric adenitis","critical":false}]', 2),
('appendix', 'Alternative RLQ Diagnoses', 'Linear 9–15 MHz; curvilinear 3–5 MHz for pelvic structures', '[{"id":"app_alt_0","label":"Assess right ovary and adnexa (women of reproductive age)","detail":"Absent Doppler flow = torsion (surgical emergency)","critical":true},{"id":"app_alt_1","label":"Assess terminal ileum wall thickness","detail":">4 mm = Crohn''s disease / ileitis","critical":false},{"id":"app_alt_2","label":"Assess mesenteric lymph nodes (cluster ≥3 nodes >5 mm)","detail":"Mesenteric adenitis — most common alternative in children","critical":false},{"id":"app_alt_3","label":"Assess right ureter for dilatation (ureteral calculus)","detail":"Absent ureteral jet on Doppler = ureteral obstruction","critical":false},{"id":"app_alt_4","label":"Assess psoas muscle for abscess (hypoechoic collection)","detail":"Psoas abscess can mimic appendicitis","critical":false},{"id":"app_alt_5","label":"Document: Appendix not visualized — CT recommended if not found","detail":"Never report normal if appendix was not directly visualized","critical":true}]', 3);

INSERT INTO navigator_overrides (module, section_name, probe, items, sort_order) VALUES
('invasive_procedures', 'Thoracentesis — Pre-Procedure Assessment', 'Curvilinear 3–5 MHz | Posterior chest wall, longitudinal plane', '[{"id":"thora_pre_0","label":"Position patient upright (tripod position) or lateral decubitus","detail":"Tripod position maximizes posterior pleural space","critical":true},{"id":"thora_pre_1","label":"Identify diaphragm (hyperechoic curvilinear structure with respiratory motion)","detail":"Confirm diaphragm position before marking site","critical":true},{"id":"thora_pre_2","label":"Measure fluid depth (minimum ≥10 mm for safe thoracentesis)","detail":"<10 mm = high risk; consider IR guidance","critical":true},{"id":"thora_pre_3","label":"Assess fluid echogenicity (anechoic vs. complex/septated)","detail":"Complex/septated = exudate or empyema — may need drain","critical":true},{"id":"thora_pre_4","label":"Confirm lung is not in the needle path","detail":"Lung above the fluid level — confirm with B-mode","critical":true},{"id":"thora_pre_5","label":"Identify optimal rib interspace (needle above superior rib margin)","detail":"Avoid subcostal groove — neurovascular bundle runs there","critical":true},{"id":"thora_pre_6","label":"Mark site with patient in procedural position","detail":"Re-scan immediately before needle insertion to confirm","critical":true},{"id":"thora_pre_7","label":"Confirm site during same respiratory phase as procedure","detail":"Diaphragm rises significantly with expiration","critical":false}]', 0),
('invasive_procedures', 'Thoracentesis — Real-Time Guidance and Post-Procedure', 'Linear 9–12 MHz (sterile cover) | Longitudinal, in-plane', '[{"id":"thora_rt_0","label":"Apply sterile transducer cover and sterile gel","detail":"Maintain sterile field throughout","critical":true},{"id":"thora_rt_1","label":"Confirm needle tip in fluid before aspirating","detail":"Real-time visualization of needle tip is essential","critical":true},{"id":"thora_rt_2","label":"Monitor for lung re-expansion during aspiration","detail":"Stop if patient develops cough or chest tightness","critical":false},{"id":"thora_rt_3","label":"Post-procedure: assess for pneumothorax (lung sliding)","detail":"Anterior chest wall, 2nd ICS, MCL — confirm seashore sign","critical":true},{"id":"thora_rt_4","label":"Absent lung sliding: look for lung point (pathognomonic for PTX)","detail":"Transition from absent to present sliding = lung point","critical":true},{"id":"thora_rt_5","label":"Assess residual pleural fluid post-procedure","detail":"Document residual volume if significant","critical":false}]', 1),
('invasive_procedures', 'Paracentesis — Pre-Procedure Assessment', 'Curvilinear 3–5 MHz | LLQ, transverse and longitudinal planes', '[{"id":"para_pre_0","label":"Position patient supine or slight lateral decubitus (affected side down)","detail":"Lateral decubitus pools fluid for easier access","critical":true},{"id":"para_pre_1","label":"Measure fluid pocket depth (minimum ≥3 cm for safe paracentesis)","detail":"<2 cm = high risk of bowel injury — reposition","critical":true},{"id":"para_pre_2","label":"Confirm no bowel loops in the needle path","detail":"Bowel shows peristalsis and layered wall — confirm absence","critical":true},{"id":"para_pre_3","label":"Identify inferior epigastric artery with color Doppler","detail":"Runs in lateral rectus sheath — must be avoided","critical":true},{"id":"para_pre_4","label":"Assess fluid echogenicity (anechoic vs. complex)","detail":"Complex fluid = exudate, hemoperitoneum, or infection","critical":false},{"id":"para_pre_5","label":"Mark optimal entry site (LLQ, lateral to rectus sheath)","detail":"Lateral to inferior epigastric artery, ≥3 cm fluid depth","critical":true},{"id":"para_pre_6","label":"Confirm no visible vessels in needle path on color Doppler","detail":"Scan the entire planned needle path with color Doppler","critical":true}]', 2),
('invasive_procedures', 'Paracentesis — Real-Time Guidance and Post-Procedure', 'Linear 9–12 MHz (sterile cover) | Longitudinal, in-plane', '[{"id":"para_rt_0","label":"Apply sterile transducer cover and sterile gel","detail":"Maintain sterile field throughout","critical":true},{"id":"para_rt_1","label":"Confirm needle tip in fluid pocket before aspirating","detail":"Real-time visualization of needle tip is essential","critical":true},{"id":"para_rt_2","label":"Monitor fluid pocket size during large-volume paracentesis","detail":"Reposition if pocket becomes <2 cm","critical":false},{"id":"para_rt_3","label":"Use Z-track technique (displace skin laterally before insertion)","detail":"Reduces post-procedure ascitic fluid leak","critical":false},{"id":"para_rt_4","label":"For LVP: albumin replacement 6–8 g per liter drained","detail":"Prevents paracentesis-induced circulatory dysfunction","critical":true},{"id":"para_rt_5","label":"Post-procedure: assess for hematoma at entry site","detail":">2 cm or expanding hematoma — apply pressure, monitor","critical":true}]', 3);

SELECT module, section_name, sort_order FROM navigator_overrides WHERE module IN ('appendix', 'invasive_procedures') ORDER BY module, sort_order;

